(function(){
  // Testimonial Carousel Scroll Behavior
  const testimonialTrack = document.querySelector(".testimonials-track")
  if (testimonialTrack) {
    let isDown = false
    let startX
    let scrollLeft

    testimonialTrack.addEventListener("mousedown", (e) => {
      isDown = true
      startX = e.pageX - testimonialTrack.offsetLeft
      scrollLeft = testimonialTrack.scrollLeft
    })
    testimonialTrack.addEventListener("mouseleave", () => {
      isDown = false
    })
    testimonialTrack.addEventListener("mouseup", () => {
      isDown = false
    })
    testimonialTrack.addEventListener("mousemove", (e) => {
      if (!isDown) return
      e.preventDefault()
      const x = e.pageX - testimonialTrack.offsetLeft
      const walk = (x - startX) * 2
      testimonialTrack.scrollLeft = scrollLeft - walk
    })
  }

  // Form Success Feedback
  const partnershipForm = document.querySelector(".partnership-form")
  if (partnershipForm) {
    partnershipForm.addEventListener("submit", (e) => {
      // Allow native submission to happen (simulated or actual)
      // We just provide visual feedback
      const submitBtn = partnershipForm.querySelector('button[type="submit"]')
      const originalText = submitBtn.innerText

      // Basic validation check before visual change
      if (partnershipForm.checkValidity()) {
        submitBtn.innerText = "Sending Inquiry..."
        submitBtn.style.opacity = "0.7"
        submitBtn.disabled = true

        // In a real scenario, the page would redirect or reload via the 'action'
        // For this demo, we'll revert after 2 seconds if it's a simulated environment
        setTimeout(() => {
          submitBtn.innerText = "Request Sent!"
          submitBtn.style.backgroundColor = "#2ecc71"
        }, 1500)
      }
    })
  }

  // Scroll Reveal Animation (Subtle)
  const observerOptions = {
    threshold: 0.1,
  }

  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        entry.target.style.opacity = "1"
        entry.target.style.transform = "translateY(0)"
      }
    })
  }, observerOptions)

  document.querySelectorAll(".cert-card, .curriculum-card, .finance-step, .onboarding-step").forEach((el) => {
    el.style.opacity = "0"
    el.style.transform = "translateY(20px)"
    el.style.transition = "opacity 0.6s ease-out, transform 0.6s ease-out"
    observer.observe(el)
  })
})()
